insert into public.artists (slug, name, kind, rank, era, roles, origin, genre, summary, bio, highlights, tags, image, initials) values
  ('the-beatles', 'The Beatles', 'group', 1, '1960–1970', '12 Album Studio Kanonik', 'Liverpool, Inggris', 'Rock / Psikedelik', 'Kuartet legendaris asal Liverpool: John Lennon, Paul McCartney, George Harrison, dan Ringo Starr.', 'Grup musik kuartet asal Liverpool yang merevolusi musik populer abad ke-20. Terdiri dari John Lennon, Paul McCartney, George Harrison, dan Ringo Starr, kemitraan penulisan lagu Lennon–McCartney menjadi standar emas musik dunia.', '', array['Abbey Road', 'Apple Corps', 'PMC / PCS Series']::text[], '/art/beatles.webp', 'TB'),
  ('john-lennon', 'John Lennon', 'solo', 2, '1940–1980', 'Vokal, Gitar, Piano', 'Liverpool, Inggris', 'Rock / Pop', '', 'Vokalis dan gitaris ritme The Beatles. John melanjutkan karier solonya dengan Plastic Ono Band dan merilis Imagine pada 1971.', 'Imagine, Plastic Ono Band, Double Fantasy.', array['Solo & Ono Band', 'Apple Records']::text[], null, 'JL'),
  ('paul-mccartney', 'Paul McCartney', 'solo', 3, '1942–Sekarang', 'Bass, Vokal, Multi-instrumentalis', 'Liverpool, Inggris', 'Rock / Pop', '', 'Bassis, vokalis, dan salah satu penulis lagu utama The Beatles. Ia memulai diskografi solonya dengan McCartney sebelum membentuk Wings.', 'McCartney, Ram, Band on the Run (Wings).', array['Wings Era', 'MPL Communications']::text[], null, 'PM'),
  ('george-harrison', 'George Harrison', 'solo', 4, '1943–2001', 'Gitaris Utama, Sitar, Penulis Lagu', 'Liverpool, Inggris', 'Rock / Folk', '', 'Gitaris utama The Beatles dan penulis Taxman, Something, serta Here Comes the Sun. Karya solonya mencakup All Things Must Pass dan Living in the Material World.', 'All Things Must Pass, Living in the Material World.', array['Dark Horse', 'Triple LP Master']::text[], null, 'GH'),
  ('ringo-starr', 'Ringo Starr', 'solo', 5, '1940–Sekarang', 'Drum, Perkusi, Vokal', 'Liverpool, Inggris', 'Rock / Pop', '', 'Richard Starkey, dikenal sebagai Ringo Starr, adalah drummer The Beatles dan penulis Octopus’s Garden. Album Ringo terbit pada 1973.', 'Ringo (1973), Beaucoups of Blues, Sentimental Journey.', array['All-Starr Band', 'Ludwig Drums']::text[], null, 'RS')
insert into public.albums (selection_art, collection_art, studio, producer, sides, slug, title, artist_slug, artist_name, rank, year, format, catalog, label, track_count, cover, artwork, edition, source_url, summary) values
  ('/art/revolver-selection.webp', '/art/revolver-collection.webp', 'EMI Studios, Abbey Road', 'George Martin', array['XEX 605', 'XEX 606']::text[], 'revolver', 'Revolver', 'the-beatles', 'The Beatles', 1, 1966, 'Mono', 'PMC 7009', 'Parlophone / EMI', 14, '/art/revolver-cover.webp', '/art/revolver.webp', 'Parlophone Mono', 'https://www.thebeatles.com/revolver', 'Dirilis pada 5 Agustus 1966. Tiga komposisi George Harrison masuk ke album ini, termasuk lagu pembuka Taxman. Eksperimen studio terdengar pada aransemen dawai Eleanor Rigby dan putaran pita Tomorrow Never Knows.'),
  ('/art/abbey-road-selection.webp', '/art/abbey-road-collection.webp', 'EMI Studios, Olympic, Trident', 'George Martin', array['YEX 749', 'YEX 750']::text[], 'abbey-road', 'Abbey Road', 'the-beatles', 'The Beatles', 2, 1969, 'Stereo', 'PCS 7088', 'Apple Records', 17, '/art/abbey-road-cover.webp', '/art/abbey-road.webp', 'Stereo Master', 'https://www.thebeatles.com/abbey-road', 'Kedua sisi album merekam pendekatan yang berbeda. Sisi kedua memuat medley dari You Never Give Me Your Money hingga The End, lalu ditutup Her Majesty, yang tersembunyi pada rilisan awal.'),
  (null, '/art/imagine-collection.webp', 'Ascot Sound Studios', 'John Lennon, Yoko Ono, Phil Spector', array[]::text[], 'imagine', 'Imagine', 'john-lennon', 'John Lennon', 3, 1971, 'Solo', 'PAS 10004', 'Apple Records', 10, '/art/imagine-cover.webp', '/art/imagine.webp', 'Apple Stereo', 'https://www.johnlennon.com/music/albums/imagine/', 'Rekaman dasar dibuat di Ascot Sound Studios. Bagian dawai The Flux Fiddlers ditambahkan di Record Plant, New York. John Lennon, Yoko Ono, dan Phil Spector memproduseri album ini.'),
  (null, null, null, 'Paul McCartney', array[]::text[], 'mccartney', 'McCartney', 'paul-mccartney', 'Paul McCartney', 4, 1970, 'Solo', 'PCS 7102', 'Apple Records', 13, '/art/mccartney-cover.webp', '/art/mccartney.webp', 'Apple Stereo', 'https://www.paulmccartney.com/discography/albums/mccartney', 'Album solo pertama Paul McCartney bermula dari percobaan dengan mesin rekam empat jalur di rumah. Paul memainkan instrumen dan menyanyikan vokal utama, sementara Linda McCartney menyumbang harmoni vokal.'),
  (null, null, 'Apple Studio', 'George Harrison', array[]::text[], 'living-in-the-material-world', 'Living in the Material World', 'george-harrison', 'George Harrison', 5, 1973, 'Solo', 'PAS 10006', 'Apple Records', 11, '/art/material-world-cover.webp', '/art/material-world.webp', 'Apple Stereo', 'https://www.georgeharrison.com/releases/living-in-the-material-world/', 'Album ini mempertemukan Harrison dengan sejumlah kolaborator All Things Must Pass dan The Concert for Bangladesh. Give Me Love (Give Me Peace on Earth) menjadi singel utama.'),
  (null, null, 'Sunset Sound Recorders', 'Richard Perry', array[]::text[], 'ringo', 'Ringo', 'ringo-starr', 'Ringo Starr', 6, 1973, 'Solo', 'PCTC 252', 'Apple Records', 10, '/art/ringo-cover.webp', '/art/ringo.webp', 'Apple Stereo', 'https://store.ringostarr.com/products/ringo-cd', 'Album solo ketiga Ringo Starr diproduseri Richard Perry. John Lennon, Paul McCartney, dan George Harrison ikut tampil serta menyumbangkan lagu, termasuk Photograph yang ditulis Ringo bersama George.')
insert into public.tracks (id, album_slug, title, position, side, duration, credit, description, annotation, writer, writing_note, source_url, writing_source_url) values
  ('taxman', 'revolver', 'Taxman', 1, 1, '2:38', 'George Harrison', null, 'Solo gitar Paul McCartney', null, 'George Harrison menulis lagu ini sebagai sindiran terhadap tingginya pajak progresif di Inggris pada masa pemerintahan Harold Wilson.', 'https://www.thebeatles.com/taxman', 'https://www.thebeatles.com/announcing-revolver-special-editions'),
  ('eleanor-rigby', 'revolver', 'Eleanor Rigby', 2, 1, '2:06', 'Lennon–McCartney', null, 'Oktet dawai George Martin', 'Paul McCartney', 'George Martin menata dua kuartet dawai untuk mengiringi lagu tentang tokoh-tokoh yang hidup dalam kesepian ini.', 'https://www.thebeatles.com/eleanor-rigby', null),
  ('im-only-sleeping', 'revolver', 'I''m Only Sleeping', 3, 1, '3:00', 'Lennon–McCartney', null, 'Gitar diputar terbalik', null, null, 'https://www.thebeatles.com/im-only-sleeping', null),
  ('love-you', 'revolver', 'Love You To', 4, 1, '2:59', 'George Harrison', null, 'Sitar dan tabla', null, null, 'https://www.thebeatles.com/love-you', null),
  ('here-there-and-everywhere', 'revolver', 'Here, There and Everywhere', 5, 1, '2:24', 'Lennon–McCartney', null, null, 'Paul McCartney', 'McCartney mengenang mulai menyusun akornya dengan gitar di tepi kolam rumah John Lennon di Weybridge.', 'https://www.thebeatles.com/here-there-and-everywhere', null),
  ('yellow-submarine', 'revolver', 'Yellow Submarine', 6, 1, '2:38', 'Lennon–McCartney', null, 'Vokal utama Ringo Starr', null, 'Pita demo memperdengarkan John Lennon menyanyikan draf awal yang bernada murung. John dan Paul kemudian mengolahnya agar selaras dengan bagian refrein yang lebih riang.', 'https://www.thebeatles.com/announcing-revolver-special-editions', null),
  ('she-said-she-said', 'revolver', 'She Said She Said', 7, 1, '2:36', 'Lennon–McCartney', null, null, 'John Lennon', 'Lennon mengaitkan liriknya dengan percakapan bersama aktor Peter Fonda pada tahun 1965.', 'https://www.thebeatles.com/she-said-she-said', null),
  ('good-day-sunshine', 'revolver', 'Good Day Sunshine', 8, 2, '2:09', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/good-day-sunshine', null),
  ('and-your-bird-can-sing', 'revolver', 'And Your Bird Can Sing', 9, 2, '2:00', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/and-your-bird-can-sing', null),
  ('for-no-one', 'revolver', 'For No One', 10, 2, '1:59', 'Lennon–McCartney', 'Baroque Pop · Menampilkan solo French horn oleh Alan Civil.', 'French Horn Solo', 'Paul McCartney', 'McCartney mengenang menulis lagu ini di sebuah chalet ketika berlibur ski di Swiss. Liriknya menggambarkan hubungan yang berakhir. John Lennon menyebutnya sebagai salah satu lagu Paul yang ia sukai.', 'https://www.thebeatles.com/no-one', 'https://www.the-paulmccartney-project.com/song/for-no-one/'),
  ('doctor-robert', 'revolver', 'Doctor Robert', 11, 2, '2:14', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/doctor-robert', null),
  ('i-want-tell-you', 'revolver', 'I Want to Tell You', 12, 2, '2:28', 'George Harrison', null, null, null, null, 'https://www.thebeatles.com/i-want-tell-you', null),
  ('got-get-you-my-life', 'revolver', 'Got to Get You into My Life', 13, 2, '2:29', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/got-get-you-my-life', null),
  ('tomorrow-never-knows', 'revolver', 'Tomorrow Never Knows', 14, 2, '2:57', 'Lennon–McCartney', 'Rock psikedelik dan eksperimental · Menggunakan loop pita dan automatic double tracking (ADT).', 'Experimental Tape Loops', 'John Lennon', 'Dalam sebuah wawancara, Lennon mengaitkan penulisan liriknya dengan The Psychedelic Experience, panduan yang mengadaptasi Tibetan Book of the Dead.', 'https://www.thebeatles.com/tomorrow-never-knows', 'https://penthouse.com/legacy/yoko-influence/'),
  ('come-together', 'abbey-road', 'Come Together', 1, 1, '4:20', 'Lennon–McCartney', null, null, 'John Lennon', 'Komposisi Lennon ini membuka Abbey Road dan dirilis sebagai singel sisi ganda bersama Something.', 'https://www.thebeatles.com/come-together', null),
  ('something', 'abbey-road', 'Something', 2, 1, '3:03', 'George Harrison', null, null, null, 'Something menjadi komposisi George Harrison pertama yang dirilis The Beatles sebagai sisi A singel.', 'https://www.thebeatles.com/something', null),
  ('maxwells-silver-hammer', 'abbey-road', 'Maxwell''s Silver Hammer', 3, 1, '3:27', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/maxwells-silver-hammer', null),
  ('oh-darling', 'abbey-road', 'Oh! Darling', 4, 1, '3:26', 'Lennon–McCartney', null, null, 'Paul McCartney', 'Judul sementara yang dipakai ketika lagu ini dikerjakan adalah Oh! Darling (I’ll Never Do You No Harm).', 'https://www.thebeatles.com/oh-darling', null),
  ('octopuss-garden', 'abbey-road', 'Octopus''s Garden', 5, 1, '2:48', 'Richard Starkey', null, null, null, null, 'https://www.thebeatles.com/octopuss-garden', null),
  ('i-want-you', 'abbey-road', 'I Want You (She''s So Heavy)', 6, 1, '7:47', 'Lennon–McCartney', null, null, 'John Lennon', 'Lennon membangun lagu hampir delapan menit ini dengan lirik yang sangat singkat dan progresi gitar berulang.', 'https://www.thebeatles.com/i-want-you', null),
