  ('golden-slumbers', 'abbey-road', 'Golden Slumbers', 14, 2, '1:31', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/golden-slumbers', null),
  ('carry-weight', 'abbey-road', 'Carry That Weight', 15, 2, '1:36', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/carry-weight', null),
  ('end', 'abbey-road', 'The End', 16, 2, '2:19', 'Lennon–McCartney', null, null, null, null, 'https://www.thebeatles.com/end', null),
  ('her-majesty', 'abbey-road', 'Her Majesty', 17, 2, '0:23', 'Lennon–McCartney', null, null, 'Paul McCartney', 'Miniatur bergaya music hall ini muncul sesudah The End dan judulnya tidak dicetak pada sampul asli.', 'https://www.thebeatles.com/her-majesty', null),
  ('imagine-imagine', 'imagine', 'Imagine', 1, 1, '3:07', 'John Lennon & Yoko Ono', null, 'Piano Lennon dan dawai The Flux Fiddlers', null, 'John Lennon menyebut buku Grapefruit karya Yoko Ono sebagai salah satu inspirasinya dan mengakui sumbangan Ono pada lirik. Arsip resmi sekarang mencantumkan keduanya sebagai penulis.', 'https://www.johnlennon.com/music/singles/imagine/', null),
